// WebReader URL object
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;public class Q18 {public static void main(String[] args)throws Exception{URL url=new URL("http://example.com");URLConnection connection=url.openConnection();connection.setConnectTimeout(5000);connection.setReadTimeout(5000);try(BufferedReader br=new BufferedReader(new InputStreamReader(connection.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=br.readLine())!=null)System.out.println(line);}}}
